{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "It would allow activities such as walking, jumping rope, volleyball, structured movement breaks, and time in physical education class when students are physically active.",
      "rationale": "The nonexclusive list conveys that walking, jumping rope, volleyball, and similar fitness activities may count as physical activity."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "It would allow activities such as walking, jumping rope, volleyball, structured movement breaks, and time in physical education class when students are physically active.",
      "rationale": "Explicitly includes structured movement breaks among permitted physical activities."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "time in physical education class when students are physically active",
      "rationale": "Includes physical education class time and preserves the condition that students must be physically active."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "Walking to and from class would not count.",
      "rationale": "Clearly excludes walking to and from class from qualifying physical activity."
    },
    {
      "proposition_id": "P5",
      "status": "partial",
      "summary_quote": "The bill would also exclude time when a student is permitted to use an electronic device from the time covered by another provision of that statute.",
      "rationale": "Conveys the electronic-device exclusion, but does not identify Section 49-6-1021(b)(2)(A)(ii). Referring only to another provision leaves the amendment's target unidentified."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "A teacher could prevent a student from participating in physical activity to improve the student’s behavior.",
      "rationale": "Preserves the teacher's authority, the action permitted, and its behavioral purpose."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "The changes would take effect July 1, 2026, and apply beginning with the 2026–2027 school year.",
      "rationale": "States the effective date and conveys ongoing application starting with the specified school year."
    }
  ]
}
